#include <stdio.h>

/* 带参宏求余数：每个参数都要加括号，防止实参是表达式时优先级出错 */
#define REM(a, b) ((a) % (b))

int main(void)
{
    int a, b;

    if (scanf("%d %d", &a, &b) != 2)
        return 1;
    printf("remainder=%d\n", REM(a, b));

    return 0;
}

#include <stdio.h>

/* 交换宏必须用 do{}while(0) 包起来，临时变量才不会漏到外层作用域 */
#define SWAP(x, y) do { int swap_tmp_ = (x); (x) = (y); (y) = swap_tmp_; } while (0)

int main(void)
{
    int a[100], b[100];
    int n, i;

    if (scanf("%d", &n) != 1)
        return 1;
    if (n < 1 || n > 100)
        return 1;

    for (i = 0; i < n; i++)
        if (scanf("%d", &a[i]) != 1)
            return 1;
    for (i = 0; i < n; i++)
        if (scanf("%d", &b[i]) != 1)
            return 1;

    for (i = 0; i < n; i++)
        SWAP(a[i], b[i]);

    for (i = 0; i < n; i++) {
        if (i > 0)
            printf(" ");
        printf("%d", a[i]);
    }
    printf("\n");
    for (i = 0; i < n; i++) {
        if (i > 0)
            printf(" ");
        printf("%d", b[i]);
    }
    printf("\n");

    return 0;
}

